1	import React, { useCallback, useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Clients feature: add a client (name + email) and list every client. Opening a client
5	// (client-open-<id>) reveals the projects being done for them — the client's own projects listing,
6	// scoped via its /api/clients/<id>/projects endpoint. Owns its own state; talks to its own
7	// /api/clients endpoints. data-testid anchors follow the spec's conventions.
8	type Client = { id: number; name: string; email: string };
9	type Project = { id: number; name: string; clientId: number; clientName: string };
10	type Contact = {
11	  id: number;
12	  clientId: number;
13	  name: string;
14	  email: string;
15	  role: string;
16	  primary: boolean;
17	};
18	type ClientSummary = { projectCount: number; contactCount: number };
19	type StatementInvoice = { id: number; projectId: number; amountDue: number };
20	type ClientStatement = { invoices: StatementInvoice[]; outstandingTotal: number };
21	
22	// Money, the way every invoice figure is shown across the app: a dollar sign and two decimals.
23	function money(amount: number): string {
24	  return `$${Number(amount).toLocaleString('en-US', {
25	    minimumFractionDigits: 2,
26	    maximumFractionDigits: 2,
27	  })}`;
28	}
29	
30	// Every client (and contact) needs a proper email. Same shape the server enforces (see CreateClient
31	// / CreateContact) so the UI and the API agree on what "valid" means.
32	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
33	function isValidEmail(value: string): boolean {
34	  return EMAIL_RE.test(value.trim());
35	}
36	
37	// Load a JSON resource from `url` into state, refetching whenever the url changes, and hand back a
38	// `reload` for callers that mutate the resource and need to pull the fresh version. Every client
39	// panel reads one url this way, so this is where that fetch-into-state pattern lives once.
40	function useJsonResource<T>(url: string, initial: T): [T, () => Promise<void>] {
41	  const [data, setData] = useState<T>(initial);
42	  const reload = useCallback(async () => {
43	    const res = await fetch(url);
44	    setData(await res.json());
45	  }, [url]);
46	  useEffect(() => {
47	    void reload();
48	  }, [reload]);
49	  return [data, reload];
50	}
51	
52	// A client's statement: all of their invoices in one place, each with what is still owed on it, and
53	// the total still owed across them all. Kept behind an opener so the client detail stays compact.
54	// Owns its own statement state, scoped to the one client it is showing; talks to that client's own
55	// /api/clients/<id>/statement endpoint.
56	function ClientStatement({ client }: { client: Client }) {
57	  const [statement] = useJsonResource<ClientStatement | null>(
58	    `/api/clients/${client.id}/statement`,
59	    null,
60	  );
61	  const [open, setOpen] = useState(false);
62	
63	  return (
64	    <section data-testid="client-statement">
65	      <button data-testid="client-statement-open" onClick={() => setOpen(true)}>
66	        Statement
67	      </button>
68	      {open && statement && (
69	        <>
70	          <table data-testid="client-statement-table">
71	            <tbody>
72	              {statement.invoices.map((inv) => (
73	                <tr key={inv.id} data-testid={`statement-invoice-row-${inv.id}`}>
74	                  <td data-testid="statement-invoice-due">{money(inv.amountDue)}</td>
75	                </tr>
76	              ))}
77	            </tbody>
78	          </table>
79	          <p data-testid="client-outstanding-total">{money(statement.outstandingTotal)}</p>
80	        </>
81	      )}
82	    </section>
83	  );
84	}
85	
86	// A client's at-a-glance counts: how many projects and contacts are kept for them. Owns its own
87	// summary state, scoped to the one client it is showing; talks to that client's own
88	// /api/clients/<id>/summary endpoint.
89	function ClientSummaryBadges({ client }: { client: Client }) {
90	  const [summary] = useJsonResource<ClientSummary>(`/api/clients/${client.id}/summary`, {
91	    projectCount: 0,
92	    contactCount: 0,
93	  });
94	
95	  return (
96	    <section data-testid="client-summary">
97	      <span data-testid="client-projects-count">{summary.projectCount}</span>
98	      <span data-testid="client-contacts-count">{summary.contactCount}</span>
99	    </section>
100	  );
101	}
102	
103	// The add-a-contact form: name, email and role, all required, with the same email check the server
104	// runs. Owns only its own field state and clears itself once the parent has taken the new contact.
105	function ContactForm({
106	  onAdd,
107	}: {
108	  onAdd: (contact: { name: string; email: string; role: string }) => Promise<void>;
109	}) {
110	  const [name, setName] = useState('');
111	  const [email, setEmail] = useState('');
112	  const [role, setRole] = useState('');
113	  const [emailError, setEmailError] = useState('');
114	
115	  async function submit(e: React.FormEvent) {
116	    e.preventDefault();
117	    if (!name.trim() || !email.trim() || !role.trim()) {
118	      return;
119	    }
120	    if (!isValidEmail(email)) {
121	      setEmailError('Enter a valid email address.');
122	      return;
123	    }
124	    setEmailError('');
125	    await onAdd({ name, email, role });
126	    setName('');
127	    setEmail('');
128	    setRole('');
129	  }
130	
131	  return (
132	    <form data-testid="contact-form" onSubmit={submit}>
133	      <input
134	        data-testid="contact-form-name"
135	        placeholder="Name"
136	        value={name}
137	        onChange={(e) => setName(e.target.value)}
138	      />
139	      <input
140	        data-testid="contact-form-email"
141	        placeholder="Email"
142	        value={email}
143	        onChange={(e) => setEmail(e.target.value)}
144	      />
145	      {emailError && (
146	        <p data-testid="contact-form-email-error" role="alert">
147	          {emailError}
148	        </p>
149	      )}
150	      <input
151	        data-testid="contact-form-role"
152	        placeholder="Role"
153	        value={role}
154	        onChange={(e) => setRole(e.target.value)}
155	      />
156	      <button data-testid="contact-form-submit" type="submit">
157	        Add contact
158	      </button>
159	    </form>
160	  );
161	}
162	
163	// The contacts list itself: a row per contact with a control to promote it to the client's primary.
164	function ContactsTable({
165	  contacts,
166	  onMakePrimary,
167	}: {
168	  contacts: Contact[];
169	  onMakePrimary: (id: number) => void;
170	}) {
171	  return (
172	    <table data-testid="client-contacts-table">
173	      <tbody>
174	        {contacts.map((ct) => (
175	          <tr key={ct.id} data-testid={`contact-row-${ct.id}`}>
176	            <td data-testid="contact-name">{ct.name}</td>
177	            <td data-testid="contact-email">{ct.email}</td>
178	            <td data-testid="contact-role">{ct.role}</td>
179	            <td>
180	              <button data-testid={`contact-primary-${ct.id}`} onClick={() => onMakePrimary(ct.id)}>
181	                Make primary
182	              </button>
183	            </td>
184	          </tr>
185	        ))}
186	      </tbody>
187	    </table>
188	  );
189	}
190	
191	// A client's contacts: the people the user keeps for them (name, email, role), with a form to add
192	// another. Owns its own contact state, scoped to the one client it is showing; talks to that
193	// client's own /api/clients/<id>/contacts endpoints. The form and the table are their own pieces so
194	// this stays a thin coordinator: load, add, promote, show who is primary.
195	function ClientContacts({ client }: { client: Client }) {
196	  const [contacts, reload] = useJsonResource<Contact[]>(`/api/clients/${client.id}/contacts`, []);
197	
198	  async function addContact(contact: { name: string; email: string; role: string }) {
199	    await fetch(`/api/clients/${client.id}/contacts`, {
200	      method: 'POST',
201	      headers: { 'Content-Type': 'application/json' },
202	      body: JSON.stringify(contact),
203	    });
204	    await reload();
205	  }
206	
207	  // Pick this contact as the client's one main contact, then refresh so the new primary shows.
208	  async function makePrimary(id: number) {
209	    await fetch(`/api/contacts/${id}/primary`, { method: 'POST' });
210	    await reload();
211	  }
212	
213	  const primary = contacts.find((ct) => ct.primary) ?? null;
214	
215	  return (
216	    <section data-testid="client-contacts">
217	      <p data-testid="client-primary-contact">{primary ? primary.name : ''}</p>
218	      <ContactForm onAdd={addContact} />
219	      <ContactsTable contacts={contacts} onMakePrimary={makePrimary} />
220	    </section>
221	  );
222	}
223	
224	// A client's detail: the projects being done for them. Owns its own project state, scoped to the one
225	// client it is showing. Reuses the project-row-<id>/project-name anchors in a client-scoped table.
226	// Shows only the client's ACTIVE projects by default (scope=active); the show-all toggle asks the
227	// server for everything (scope=all), so the finished and hidden (archived) ones appear too.
228	function ClientProjects({ client }: { client: Client }) {
229	  const [showAll, setShowAll] = useState(false);
230	  const [projects] = useJsonResource<Project[]>(
231	    `/api/clients/${client.id}/projects?scope=${showAll ? 'all' : 'active'}`,
232	    [],
233	  );
234	
235	  return (
236	    <section data-testid="client-projects">
237	      <button data-testid="client-projects-show-all" onClick={() => setShowAll((v) => !v)}>
238	        {showAll ? 'Show only active' : 'Show finished and hidden too'}
239	      </button>
240	      <table data-testid="client-projects-table">
241	        <tbody>
242	          {projects.map((p) => (
243	            <tr key={p.id} data-testid={`project-row-${p.id}`}>
244	              <td data-testid="project-name">{p.name}</td>
245	            </tr>
246	          ))}
247	        </tbody>
248	      </table>
249	    </section>
250	  );
251	}
252	
253	// A name-and-email form for a client, used to add one and reusable for correcting one. `testid` is
254	// the anchor prefix (its fields are `${testid}-name` / `-email` / `-email-error` / `-submit`), so a
255	// second instance (e.g. an edit form) just passes a different prefix. Validates the email format the
256	// way the server does; `onSubmit` returns an error string to show (e.g. a duplicate the server
257	// rejected) or null on success, in which case the form clears back to its initial values.
258	function ClientForm({
259	  testid,
260	  submitLabel,
261	  initial = { name: '', email: '' },
262	  onSubmit,
263	}: {
264	  testid: string;
265	  submitLabel: string;
266	  initial?: { name: string; email: string };
267	  onSubmit: (values: { name: string; email: string }) => Promise<string | null>;
268	}) {
269	  const [name, setName] = useState(initial.name);
270	  const [email, setEmail] = useState(initial.email);
271	  const [emailError, setEmailError] = useState('');
272	
273	  async function submit(e: React.FormEvent) {
274	    e.preventDefault();
275	    if (!isValidEmail(email)) {
276	      setEmailError('Enter a valid email address.');
277	      return;
278	    }
279	    const error = await onSubmit({ name, email });
280	    if (error) {
281	      setEmailError(error);
282	      return;
283	    }
284	    setEmailError('');
285	    setName(initial.name);
286	    setEmail(initial.email);
287	  }
288	
289	  return (
290	    <form data-testid={testid} onSubmit={submit}>
291	      <input
292	        data-testid={`${testid}-name`}
293	        placeholder="Name"
294	        value={name}
295	        onChange={(e) => setName(e.target.value)}
296	      />
297	      <input
298	        data-testid={`${testid}-email`}
299	        placeholder="Email"
300	        value={email}
301	        onChange={(e) => setEmail(e.target.value)}
302	      />
303	      {emailError && (
304	        <p data-testid={`${testid}-email-error`} role="alert">
305	          {emailError}
306	        </p>
307	      )}
308	      <button data-testid={`${testid}-submit`} type="submit">
309	        {submitLabel}
310	      </button>
311	    </form>
312	  );
313	}
314	
315	// The client list: a row per client with controls to open its detail or archive it.
316	function ClientsTable({
317	  clients,
318	  onOpen,
319	  onArchive,
320	}: {
321	  clients: Client[];
322	  onOpen: (id: number) => void;
323	  onArchive: (id: number) => void;
324	}) {
325	  return (
326	    <table data-testid="clients-table">
327	      <tbody>
328	        {clients.map((c) => (
329	          <tr key={c.id} data-testid={`client-row-${c.id}`}>
330	            <td data-testid="client-name">{c.name}</td>
331	            <td data-testid="client-email">{c.email}</td>
332	            <td>
333	              <button data-testid={`client-open-${c.id}`} onClick={() => onOpen(c.id)}>
334	                Open
335	              </button>
336	              <button data-testid={`client-archive-${c.id}`} onClick={() => onArchive(c.id)}>
337	                Archive
338	              </button>
339	            </td>
340	          </tr>
341	        ))}
342	      </tbody>
343	    </table>
344	  );
345	}
346	
347	function ClientsPage() {
348	  const [clients, reload] = useJsonResource<Client[]>('/api/clients', []);
349	  // Client-side name filter: the list can get long, so a search box narrows it. Case-insensitive
350	  // substring match on the client name; an empty box shows everyone.
351	  const [search, setSearch] = useState('');
352	  const [openId, setOpenId] = useState<number | null>(null);
353	
354	  // Two clients cannot share an email; the server rejects a duplicate, so surface it and keep the
355	  // form as-is rather than clearing or reloading (nothing was added).
356	  async function addClient(values: { name: string; email: string }): Promise<string | null> {
357	    const res = await fetch('/api/clients', {
358	      method: 'POST',
359	      headers: { 'Content-Type': 'application/json' },
360	      body: JSON.stringify(values),
361	    });
362	    if (!res.ok) {
363	      return 'A client with this email already exists.';
364	    }
365	    await reload();
366	    return null;
367	  }
368	
369	  // Tuck a client away: archived clients are retained server-side but drop off this list and out of
370	  // the search. Reloading after archiving is enough — the /api/clients list excludes them.
371	  async function archive(id: number) {
372	    await fetch(`/api/clients/${id}/archive`, { method: 'POST' });
373	    if (openId === id) {
374	      setOpenId(null);
375	    }
376	    await reload();
377	  }
378	
379	  const term = search.trim().toLowerCase();
380	  const visible = clients.filter((c) => c.name.toLowerCase().includes(term));
381	  const open = clients.find((c) => c.id === openId) ?? null;
382	
383	  return (
384	    <section data-testid="clients">
385	      <input
386	        data-testid="client-search"
387	        placeholder="Search clients by name"
388	        value={search}
389	        onChange={(e) => setSearch(e.target.value)}
390	      />
391	      <ClientForm testid="client-form" submitLabel="Add client" onSubmit={addClient} />
392	
393	      {clients.length === 0 ? (
394	        <p data-testid="clients-empty">No clients yet.</p>
395	      ) : (
396	        <ClientsTable clients={visible} onOpen={setOpenId} onArchive={archive} />
397	      )}
398	
399	      {open && <ClientSummaryBadges key={`summary-${open.id}`} client={open} />}
400	      {open && <ClientStatement key={`statement-${open.id}`} client={open} />}
401	      {open && <ClientContacts key={`contacts-${open.id}`} client={open} />}
402	      {open && <ClientProjects key={open.id} client={open} />}
403	    </section>
404	  );
405	}
406	
407	export const feature: Feature = { id: 'clients', label: 'Clients', Page: ClientsPage };
